import networkx as nx
G = nx.Graph()
for i in range(15):
    for j in range(i+1, 15):
        if (i // 3) == (j // 3):
            G.add_edge(i, j)
if nx.algorithms.coloring.greedy_color(G) <= 4 and nx.algorithms.cycles.girth(G) >= 8 and G.number_of_edges() >= 24:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
